def compute(vars):
    old = vars["v1"]  # Q3 2015 HQLA
    new = vars["v2"]  # Q4 2015 HQLA

    if old == 0:
        return {"value": None, "trace": {"output_meta": {"currency": None, "scale": "ones", "unit": "percentage"}}}

    change = new - old
    value = change / old * 100

    return {
        "value": value,
        "trace": {
            "old": old,
            "new": new,
            "change": change,
            "change_ratio": change / old,
            "output_meta": {"currency": None, "scale": "ones", "unit": "percentage"},
        },
    }
